## Sample data given into a variable
DNA = "TCAATGCATGCGGGTCTATATGCAT"

def is_reverse_palindrome(sub):
  return sub == reverse_complements(sub)

def reverse_complement(s):
  comp = {'A':'T', 'T':'A', 'C':'G', 'G':'C'}
  rev = ""
  for base in reversed(s):
    rev += comp[base]
  return rev

def is_reverse_palindrome(sub):
  return sub == reverse_complement(sub)

def find_reverse_palidromes(s):
  results = []
  n = len(s)

  for i in range(n):
    for length in range(4, 13):
      end = i + length
      if end > n:
        continue

      sub = s[i:end]

      if is_reverse_palindrome(sub):
        results.append((i + 1, length))

    return results

